/**
 * The Bloodletting Hour — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { BLOODLETTING_HOUR_TEMPLATE } from '../bloodletting-hour';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Bloodletting Hour — template structure", () => {
  it('carries its identity', () => {
    expect(BLOODLETTING_HOUR_TEMPLATE.id).toBe('encounter.town.bloodletting_hour');
    expect(BLOODLETTING_HOUR_TEMPLATE.reach).toBe('star');
    expect(BLOODLETTING_HOUR_TEMPLATE.rarityTier).toBe(2);
    expect(BLOODLETTING_HOUR_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = BLOODLETTING_HOUR_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['bleeding.remember_the_nights', 'bleeding.fix_the_sums']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['order', 'time']);
  });

  it('step 1 deals the authored hand', () => {
    const step = BLOODLETTING_HOUR_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['bleeding.blunt_the_blade', 'bleeding.warm_the_chamber']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['energy', 'matter']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(BLOODLETTING_HOUR_TEMPLATE.settings).toEqual(['urban']);
    expect(BLOODLETTING_HOUR_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(BLOODLETTING_HOUR_TEMPLATE.consequenceDraw).toEqual(['knowledge', 'secret']);
    expect(BLOODLETTING_HOUR_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.bloodletting_hour',
          reach: 'star',
          rarityTier: 2,
        }),
        BLOODLETTING_HOUR_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
